/**
 * The AI deadline-accuracy audit (plan s08 8.13, s10's press plan, REQ-039). Novus asks consumer
 * AI assistants for the deadlines of 50 program cycles, scores the answers against deadlines two
 * people verified on the official pages, and publishes the scored table.
 *
 * The protocol, schedule and rubric below are the pre-registered plan. Results exist only once a
 * report is added to AUDIT_REPORTS; until then the page says when the first one publishes and
 * shows no numbers. Nothing here is generated by a model, and no number is about a student.
 */

export const AUDIT_PATH = "/research/ai-deadline-audit";

/** "2027-01": a dated edition of the report, served under the canonical path. */
export const REPORT_ID = /^\d{4}-(0[1-9]|1[0-2])$/;

export interface AuditMilestone {
  /** ISO dates; `end` is the last day of a span, or equal to `start`. */
  readonly start: string;
  readonly end: string;
  readonly label: string;
  readonly detail: string;
}

/** The pre-registered schedule for the first edition (plan s08 8.13). */
export const AUDIT_SCHEDULE: readonly AuditMilestone[] = [
  { start: "2026-12-28", end: "2026-12-28", label: "Protocol published", detail: "The full protocol is fixed and its hash published, before any question is asked." },
  { start: "2027-01-02", end: "2027-01-02", label: "Sample frozen", detail: "50 program cycles chosen across six strata, then locked." },
  { start: "2027-01-04", end: "2027-01-06", label: "Ground truth", detail: "Two people verify each deadline on the official page, independently, before seeing Novus's value." },
  { start: "2027-01-05", end: "2027-01-09", label: "Assistants asked", detail: "Each question typed by hand into ChatGPT, Gemini and Claude, free tier, fresh accounts, memory off." },
  { start: "2027-01-09", end: "2027-01-09", label: "Re-check", detail: "Every official page is checked again; any page that changed is verified again." },
  { start: "2027-01-12", end: "2027-01-20", label: "Connector arm", detail: "The same questions in Claude Free with Novus connected, once Novus's connector has run for a week." },
  { start: "2027-01-19", end: "2027-01-19", label: "Vendors told", detail: "Each company receives its own results before anyone else." },
  { start: "2027-01-27", end: "2027-01-27", label: "Report published", detail: "Methods, the scored table with evidence, screenshots, Novus's own errors and the limitations." },
];

export const AUDIT_PROMPT = "What is the application deadline for [program] for the 2027 cycle? Include the time zone and your source.";

export const AUDIT_STRATA: readonly string[] = [
  "Early-insight and sophomore programs",
  "Leadership and diversity cohorts",
  "Summer research",
  "National undergraduate awards",
  "Pre-professional pipelines",
  "Federal programs",
];

export type AuditGrade = "correct" | "partly_correct" | "incorrect" | "no_answer";

export const AUDIT_GRADES: readonly { grade: AuditGrade; label: string; rule: string }[] = [
  { grade: "correct", label: "Correct", rule: "The right date for the 2027 cycle, plus the time, zone and campus or national scope wherever the official page states them." },
  { grade: "partly_correct", label: "Partly correct", rule: "The right date with the wrong year, cycle or scope." },
  { grade: "incorrect", label: "Incorrect", rule: "A wrong date, a past cycle given as current, or an ended program given as open." },
  { grade: "no_answer", label: "No answer", rule: "The assistant declined or gave no date." },
];

/** One assistant and arm's scored answers. Counts are over the same 50 cycles. */
export interface AuditArmResult {
  readonly assistant: string;
  /** "Main (free tier)", "With the Novus connector", "Novus's own published deadlines". */
  readonly arm: string;
  readonly plan: string;
  readonly modelLabel: string;
  readonly correct: number;
  readonly partlyCorrect: number;
  readonly incorrect: number;
  readonly noAnswer: number;
  /** Answers whose cited source does not support them (counted separately from the grade). */
  readonly unsupportedCitations: number;
}

export interface AuditReport {
  readonly id: string;
  readonly title: string;
  readonly publishedOn: string;
  readonly sampleSize: number;
  readonly arms: readonly AuditArmResult[];
  /** Cohen's kappa between the two scorers. */
  readonly kappa: number | null;
  /** Novus's monthly random-sample accuracy (REQ-022), labelled separately; never the audit's ground truth. */
  readonly pooledNovusAccuracy: { readonly correct: number; readonly n: number; readonly window: string } | null;
  readonly limitations: readonly string[];
  /** Where the screenshots, raw answers and grades are published. */
  readonly evidenceUrl: string | null;
  /** True for invented fixtures (tests, previews); such a report is labelled and never indexed. */
  readonly isSample: boolean;
}

/** Published editions, newest first. Empty until the first report is published (27 Jan 2027). */
export const AUDIT_REPORTS: readonly AuditReport[] = [];

export function totalOf(arm: AuditArmResult): number {
  return arm.correct + arm.partlyCorrect + arm.incorrect + arm.noAnswer;
}

/**
 * Wilson score interval for k successes in n trials (z = 1.96 for 95%), as proportions. The plan's
 * worked example: 45 of 50 gives 0.79 to 0.96.
 */
export function wilsonInterval(k: number, n: number, z = 1.96): { low: number; high: number } {
  if (n <= 0 || k < 0 || k > n) return { low: 0, high: 0 };
  const p = k / n;
  const z2 = z * z;
  const denom = 1 + z2 / n;
  const centre = (p + z2 / (2 * n)) / denom;
  const half = (z * Math.sqrt((p * (1 - p)) / n + z2 / (4 * n * n))) / denom;
  return { low: Math.max(0, centre - half), high: Math.min(1, centre + half) };
}

/** "45 of 50 (90%; 95% interval 79 to 96%)": counts first, the share and its interval after. */
export function accuracyText(k: number, n: number): string {
  if (n <= 0) return "no answers scored";
  const { low, high } = wilsonInterval(k, n);
  const pct = (x: number): number => Math.round(x * 100);
  return `${k} of ${n} (${pct(k / n)}%; 95% interval ${pct(low)} to ${pct(high)}%)`;
}

export type MilestoneState = "done" | "now" | "planned";

export function milestoneState(m: AuditMilestone, todayIso: string): MilestoneState {
  if (todayIso > m.end) return "done";
  if (todayIso >= m.start) return "now";
  return "planned";
}

export function findReport(id: string, reports: readonly AuditReport[] = AUDIT_REPORTS): AuditReport | null {
  return reports.find((r) => r.id === id) ?? null;
}

/** The edition the canonical page leads with: the newest real one, else null. */
export function latestReport(reports: readonly AuditReport[] = AUDIT_REPORTS): AuditReport | null {
  return reports.find((r) => !r.isSample) ?? null;
}

/** The date the first report is due, from the schedule. */
export function plannedPublication(): string {
  return AUDIT_SCHEDULE[AUDIT_SCHEDULE.length - 1]?.end ?? "";
}
